"""New Year flow: calendar, wheel settlement, raffle and cookie reveal."""
from compare import serve
from playwright.sync_api import sync_playwright

def check_feature(browser,port,errors,check):
    page=browser.new_page(viewport={'width':375,'height':667})
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
    base=f'http://127.0.0.1:{port}/features/advent/'
    page.goto(base+'?state=home-first')
    js=page.evaluate
    page.evaluate('document.fonts.ready')
    check('first login is credited automatically before opening a card',js('AV.S.balance')==30 and js('AV.S.days[0].login')=='claimed' and page.locator('.av-today__open').evaluate('e=>{const r=e.getBoundingClientRect(),nav=document.querySelector(".av-entries").getBoundingClientRect();return r.top>0&&r.bottom<innerHeight&&r.bottom<nav.top;}'))
    home=page.locator('#screen-home')
    check('unseen fact has the requested title and primary watch action',page.locator('#today-title').inner_text()=='каждый день — новый факт о тебе' and page.locator('.av-today__open.button--primary').inner_text()=='СМОТРЕТЬ' and not page.locator('.av-today__date,.av-today__lead,.av-today__seen').count())
    check('collection contains 18 unique prizes',js('AV.D.POOL.length')==18 and js('new Set(AV.D.POOL.map(p=>p.id)).size')==18)
    check('miniature uses eight eligible prizes without preparing a spin',page.locator('#home-wheel-preview .nw-sector').count()==8 and js('AV_GAME.state().offers')==[] and js('AV.S.taken')==[])
    check('tasks show a title, description and reward without decorative illustrations',home.locator('.av-task').count()==3 and home.locator('.av-task__reward').all_text_contents()==['30','30','30'] and home.locator('.av-task__description').evaluate_all('els=>els.every(e=>e.textContent.trim())') and not home.locator('.av-task__art,.av-task__obj').count() and home.locator('.av-task img').evaluate_all('els=>els.every(e=>e.classList.contains("av-task__flake"))'))
    check('tasks offer textual instructions and no collection or completion buttons',not home.locator('[data-claim],[data-do]').count() and home.locator('.av-task__info').all_text_contents()==['инструкция','инструкция'] and not home.locator('.av-task__info .icon--about').count() and home.locator('[data-row="login"] .av-task__state').get_attribute('aria-label')=='выполнено')
    check('single sentence descriptions do not end in a period',home.locator('.av-task__description').evaluate_all('els=>els.every(e=>!e.textContent.endsWith("."))') and js('AV.D.DAYS.every(d=>!d.task.description.endsWith(".")&&((d.task.instruction.match(/[.!?](?:\\s|$)/g)||[]).length>1||!d.task.instruction.endsWith(".")))'))
    check('tasks and calendar section titles use the same typography',js('() => {const a=getComputedStyle(document.querySelector("#today-tasks-title")),b=getComputedStyle(document.querySelector("#calendar-title"));return a.fontSize===b.fontSize&&a.fontWeight===b.fontWeight&&a.fontFamily===b.fontFamily;}'))
    check('rewards align on one right edge in completed and available tasks',home.locator('.av-task__reward').evaluate_all('els=>Math.max(...els.map(e=>e.getBoundingClientRect().right))-Math.min(...els.map(e=>e.getBoundingClientRect().right))<1'))
    check('text instruction has a full touch target without a filled pill',home.locator('.av-task__info').evaluate_all('els=>els.every(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return s.backgroundColor==="rgba(0, 0, 0, 0)"&&document.elementFromPoint(r.x+r.width/2,r.top-4)?.closest("button")===e&&document.elementFromPoint(r.x+r.width/2,r.bottom+4)?.closest("button")===e;})'))
    check('every task reward puts the snowflake after its number',home.locator('.av-task__reward').evaluate_all('els=>els.every(e=>e.firstElementChild.tagName==="SPAN"&&e.firstElementChild.nextElementSibling.tagName==="IMG"&&e.firstElementChild.getBoundingClientRect().right<=e.querySelector("img").getBoundingClientRect().left)'))
    check('compact prize entries retain filled surfaces and navigation affordance',home.locator('.av-entry').evaluate_all('els=>els.every(e=>{const s=getComputedStyle(e);return s.backgroundColor==="rgb(26, 26, 26)"&&e.clientHeight>=60&&e.querySelector(".icon--chevron");})') and page.locator('.av-entries').evaluate('e=>e.getBoundingClientRect().bottom<innerHeight&&e.getBoundingClientRect().bottom<document.querySelector("#home-tasks").getBoundingClientRect().top'))
    page.locator('.av-today__open').click();page.wait_for_timeout(500)
    check('watch opens statistics directly without a second login grant',js('AV.stack')==['home','stat'] and js('AV.S.balance')==30 and page.locator('#stat-title').inner_text()=='заходы в blink' and not page.locator('#screen-day').is_visible())
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('statistics close directly to home without scrolling or hiding the art',js('AV.current()')=='home' and page.locator('#home-scroll').evaluate('e=>e.scrollTop<1') and page.locator('.av-today__art').is_visible())
    check('viewed fact exposes its topic, status and secondary repeat action',page.locator('#home-today.is-seen').count()==1 and page.locator('#today-title').inner_text()=='заходы в blink' and page.locator('.av-today__seen').inner_text()=='факт просмотрен' and page.locator('.av-today__open.button--secondary').inner_text()=='ПОСМОТРЕТЬ ЕЩЁ РАЗ')
    home.locator('[data-task-help="task"]').click();page.wait_for_selector('#sheet-task.is-open')
    check('task instruction explains the action without completing it',page.locator('#task-help-title').inner_text()=='друзья на карте' and 'карту' in page.locator('#task-help-text').inner_text() and js('AV.S.balance')==30 and js('AV.S.days[0].task')=='todo')
    page.locator('#task-help-action').click();page.wait_for_timeout(450)
    home.locator('[data-row="task"]').scroll_into_view_if_needed()
    row_y=home.locator('[data-row="task"]').evaluate('e=>e.getBoundingClientRect().y')
    js('window.dispatchEvent(new CustomEvent("advent:task-completed",{detail:{day:0,key:"task"}}))')
    check('a completion event credits the reward immediately and updates its row',js('AV.S.balance')==60 and home.locator('[data-row="task"].is-done').count()==1 and not home.locator('[data-task-help="task"]').count())
    check('automatic completion does not move the row',abs(home.locator('[data-row="task"]').evaluate('e=>e.getBoundingClientRect().y')-row_y)<1)
    js('window.dispatchEvent(new CustomEvent("advent:task-completed",{detail:{day:0,key:"task"}}));window.dispatchEvent(new CustomEvent("advent:task-completed",{detail:{day:1,key:"task"}}));window.dispatchEvent(new CustomEvent("advent:task-completed",{detail:{day:0,key:"invalid"}}))')
    check('duplicate, wrong-day and unknown-task events cannot add another reward',js('AV.S.balance')==60 and js('AV.S.events.filter(e=>e.name==="newyear_task_complete"&&e.key==="task").length')==1)
    home.locator('[data-task-help="share"]').click();page.locator('#task-help-action').click();page.wait_for_timeout(500)
    check('share task opens the card but does not award a cancelled share',js('AV.current()')=='stat' and js('AV.S.days[0].share')=='todo' and js('AV.S.balance')==60)
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('cancelled share remains available on home without collection controls',home.locator('[data-task-help="share"]').is_visible() and not home.locator('[data-claim]').count())
    home.locator('[data-task-help="share"]').click();page.locator('#task-help-action').click();page.wait_for_timeout(500)
    page.locator('#stat-share').click();page.locator('#share-cta').click(click_count=2)
    page.wait_for_function('!document.querySelector("#sheet-share").classList.contains("is-open")')
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('actual share credits once automatically without a collection step',home.locator('[data-row="share"].is-done').count()==1 and js('AV.S.balance')==90 and js('AV.S.days[0].share')=='claimed')
    check('completed tasks retain their statuses and repeat stays available',home.locator('.av-task__state').count()==3 and not home.locator('[data-claim],[data-do],.av-task__info').count() and page.locator('.av-today__open').inner_text()=='ПОСМОТРЕТЬ ЕЩЁ РАЗ')
    js("AV.showState('home-late')")
    page.locator('.av-today__open').click();page.wait_for_timeout(500)
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('uncracked prediction remains unseen after closing',not js('AV.S.days[AV.S.today].seen') and not page.locator('#home-today.is-seen').count())
    page.locator('.av-today__open').click();page.wait_for_timeout(500)
    page.locator('#stat-share').click();page.wait_for_selector('.avc.is-cracked')
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('revealed prediction becomes viewed',js('AV.S.days[AV.S.today].seen') and page.locator('.av-today__seen').inner_text()=='предсказание прочитано')
    for width,height in [(375,667),(390,844),(430,932)]:
        page.set_viewport_size({'width':width,'height':height})
        all_fit=True
        illustrations=set()
        for day in range(29):
            js(f'AV.resetTo({day})')
            illustrations.add(tuple(page.locator('.av-today__art img').evaluate_all('els=>els.map(e=>e.getAttribute("src"))')))
            all_fit=all_fit and js("() => {\n const hero=document.querySelector('#home-today'),title=hero.querySelector('h2'),button=hero.querySelector('.av-today__open'),r=button.getBoundingClientRect();\n return title.scrollWidth<=title.clientWidth+1&&r.right<=innerWidth&&r.bottom<innerHeight&&document.querySelector('#home-scroll').scrollTop<1&&document.querySelector('.av-entries').getBoundingClientRect().bottom<innerHeight&&[...document.querySelectorAll('#home-tasks .av-task')].every(e=>{\n  const b=e.getBoundingClientRect(),t=e.querySelector('.av-task__text'),reward=e.querySelector('.av-task__reward'),body=e.querySelector('.av-task__body'),tr=t.getBoundingClientRect(),rr=reward.getBoundingClientRect();\n  return b.right<=innerWidth&&t.scrollWidth<=t.clientWidth+1&&tr.height<=21&&tr.right<=rr.left-4&&Math.abs((tr.top+tr.bottom-rr.top-rr.bottom)/2)<3&&(!body||(()=>{\n   const d=e.querySelector('.av-task__description').getBoundingClientRect(),a=body.querySelector('button,.av-task__expired').getBoundingClientRect();return d.top>=tr.bottom&&d.right<=a.left-8&&a.right<=b.right;\n  })());\n });\n}")
        check(f'all 29 daily illustrations differ with readable tasks and visible prize actions at {width}',all_fit and len(illustrations)==29)
        js('AV.resetTo(0)')
        check(f'calendar begins in the first viewport at {width}',page.locator('.av-cell__art').first.evaluate('e=>e.getBoundingClientRect().top<innerHeight-24') and page.locator('#calendar-title').evaluate('e=>e.getBoundingClientRect().bottom<innerHeight'))
    page.set_viewport_size({'width':375,'height':667})
    gallery_tasks_fit=True
    for state in ['day-today','day-claimed','day-boost','day-prediction']:
        js(f'AV.showState({state!r})')
        gallery_tasks_fit=gallery_tasks_fit and js('AV.current()')=='day' and page.locator('#screen-day .av-task').count()==3
    check('daily gallery states show the restored day screen',gallery_tasks_fit)
    page.emulate_media(reduced_motion='reduce')
    every_day_opens=True
    for day in range(29):
        js(f'AV.resetTo({day})')
        page.locator(f'[data-day="{day}"]').click()
        every_day_opens=every_day_opens and js('AV.stack')==['home','day'] and page.locator('#day-title').inner_text()==js(f'AV.D.DAYS[{day}].title')
        page.locator('#screen-day [data-act="back"]').click()
    check('each of the 29 available calendar days opens its own day screen',every_day_opens)
    page.emulate_media(reduced_motion='no-preference')
    page.goto(base+'?state=home')
    check('home title and two reward destinations',page.locator('#home-title').inner_text()=='новый год' and page.locator('.av-entry').count()==2)
    check('shelves removed while frost and ice are retained',not page.locator('.av-ledge').count() and page.locator('.av-frost').is_visible() and page.locator('.av-cell.is-frozen .av-cell__ice').count()==20)
    check('every date is below its object',page.locator('.av-cell').evaluate_all('els=>els.every(e=>e.querySelector(".av-cell__date").getBoundingClientRect().top>=e.querySelector(".av-cell__art").getBoundingClientRect().bottom)'))
    check('calendar has no range and restores large objects and dates',not page.locator('.av-calendar__head span').count() and page.locator('.av-cell__art').first.evaluate('e=>e.clientWidth>=100') and page.locator('.av-cell.is-frozen .av-cell__date').first.evaluate('e=>parseFloat(getComputedStyle(e).fontSize)>=16'))
    page.evaluate('document.fonts.ready')
    label_probe='els=>els.every(e=>{const range=document.createRange();range.selectNodeContents(e);const r=range.getBoundingClientRect(),b=e.closest("button").getBoundingClientRect();return r.left>=b.left+4&&r.right<=b.right-4;})'
    old_layout=page.add_style_tag(content='.av-entries{grid-template-columns:1.2fr 1fr}.av-home .av-entry{display:flex;padding:0 12px 0 6px}.av-home .av-entry__arrow{display:none}.av-home .av-entry__art{width:52px;height:52px}.av-home .av-entry__title{font:var(--type-row-title)}')
    check('label probe rejects the previously clipped layout',not page.locator('.av-entry__title').evaluate_all(label_probe))
    old_layout.evaluate('e=>e.remove()')
    page.locator('[data-day="10"]').click();page.wait_for_timeout(450)
    check('future days remain closed',js("AV.current()")=='home')
    page.locator('[data-day="8"]').click();page.wait_for_timeout(700)
    check('today calendar cell opens the original day screen',js('AV.stack')==['home','day'] and page.locator('#day-title').inner_text()=='голосовые')
    page.locator('#screen-day [data-act="back"]').click();page.wait_for_timeout(700)
    page.locator('[data-day="2"]').click();page.wait_for_timeout(700)
    check('past calendar days keep their history screen',js('AV.current()')=='day' and page.locator('#day-title').inner_text()=='путь за год')
    page.locator('#screen-day [data-act="open-stat"]').click();page.wait_for_timeout(500)
    check('past December card still opens',page.locator('#screen-stat').is_visible() and page.locator('#stat-title').inner_text()=='путь за год')
    page.locator('[data-act="close-stat"]').click();page.wait_for_timeout(400)
    check('closing past statistics returns to the same historical day',js('AV.current()')=='day' and page.locator('#day-title').inner_text()=='путь за год')
    page.locator('#screen-day [data-act="back"]').click();page.wait_for_timeout(700)
    old_balance=js('AV.S.balance');past=js('AV.S.days[2]')
    js('window.dispatchEvent(new CustomEvent("advent:task-completed",{detail:{day:8,key:"task"}}))')
    check('completion belongs to today even after viewing a past day',js('AV.S.days[8].task')=='claimed' and js('AV.S.days[2]')==past and js('AV.S.balance')==old_balance+30)
    page.goto(base+'?state=wheel-first')
    check('wheel price also puts its snowflake after the amount',page.locator('.nw-price').evaluate('e=>e.firstChild.nodeType===Node.TEXT_NODE&&e.firstChild.textContent.trim()==="30"&&e.lastElementChild.tagName==="IMG"'))
    check('wheel shows eight unique available prizes without the promise label',len(set(js('AV_GAME.state().offers')))==8 and page.locator('#game .nw-sector').count()==8 and not page.locator('.nw-promise').count() and page.locator('[data-game="wheel-spin"]').count()==1)
    check('product contains no technical labels',not page.locator('#game').filter(has_text='демо').count())
    before=js('[AV.S.balance,AV.S.tickets,AV.S.taken.length]');offers_before=js('AV_GAME.state().offers')
    page.locator('[data-game="wheel-spin"]').click()
    award=js('AV_GAME.state().award')
    check('paid spin reserves one unique item and one ticket',js('[AV.S.balance,AV.S.tickets,AV.S.taken.length]')==[before[0]-30,before[1]+1,before[2]+1])
    check('wheel visibly spins, no result leaked to feed',page.locator('#game .nw-rotor').evaluate("e=>e.getAnimations().some(a=>a.playState==='running')") and not page.locator('.nw-recent').filter(has_text='ты').count())
    js("AV_GAME.click({dataset:{game:'wheel-spin'}},AV.gameCtx())")
    check('duplicate input cannot charge twice',js('AV.S.balance')==before[0]-30)
    page.wait_for_selector('.nw-result')
    check('automatic result matches the actual credited prize',page.locator('.nw-result h4').inner_text()==award['prize']['title'] and js('AV.S.taken.includes(AV_GAME.state().award.prize.id)'))
    page.locator('[data-game="wheel-again"]').click()
    offers_after=js('AV_GAME.state().offers');won=award['prize']['id'];won_index=offers_before.index(won)
    check('won slot is replaced and the other seven prizes keep their slots',won not in offers_after and offers_after[won_index] not in offers_before and all(a==b for i,(a,b) in enumerate(zip(offers_before,offers_after)) if i!=won_index) and len(set(offers_after))==8)
    check('recent feed includes player after reveal',page.locator('.nw-recent b').first.inner_text()=='ты')
    page.locator('[data-game="wheel-spin"]').click();page.wait_for_timeout(700)
    check('zero balance goes straight to visible home tasks without another charge',js('AV.S.balance')==0 and js('AV.current()')=='home' and home.locator('[data-task-help="task"]').is_visible() and home.locator('#home-tasks').evaluate('e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<innerHeight;}'))
    page.goto(base+'?state=wheel')
    page.locator('[data-game="wheel-spin"]').click()
    settled=js('[AV.S.balance,AV.S.tickets,AV.S.taken.length]')
    page.locator('#screen-game [data-act="back"]').click();page.wait_for_timeout(400)
    page.locator('.av-entry[data-go="game"]').click();page.wait_for_selector('.nw-result')
    check('leaving a spin keeps the same awarded prize',js('[AV.S.balance,AV.S.tickets,AV.S.taken.length]')==settled)
    page.locator('[data-game="wheel-draw"]').click();page.wait_for_timeout(500)
    check('raffle uses four ordinary prize choices without tickets or carousel',page.locator('.avd-prize').count()==4 and not page.locator('.avd-ticket,#draw-carousel,[src*="globe-"]').count())
    stable=js("() => Object.fromEntries(['.avd-info__chance','.avd-put','.avd-cta'].map(s=>[s,document.querySelector(s).getBoundingClientRect().y]))")
    for index in [0,1,2,3]:
        page.locator(f'[data-draw="select"][data-prize="{index}"]').click()
        check('raffle controls stay fixed while prizes change',js("(old) => Object.entries(old).every(([s,y])=>Math.abs(document.querySelector(s).getBoundingClientRect().y-y)<1)",stable))
    check('raffle uses system type and neutral selected choice styling',page.locator('.avd-prize__title').first.evaluate("e=>getComputedStyle(e).fontFamily.includes('Montserrat')") and page.locator('.avd-prize[aria-pressed="true"]').count()==1 and page.locator('.avd-prize.is-selected').evaluate('e=>getComputedStyle(e).borderTopColor==="rgb(255, 255, 255)"'))
    js('document.querySelector("[data-panel=tickets]").click()')
    check('side panel provides exactly thirty tickets',js('AV.S.tickets')==30 and page.locator('#screen-draw [data-tickets]').inner_text()=='30')
    js('for(let i=0;i<40;i++)document.querySelector("[data-draw=plus]").click()')
    check('raffle ticket quantity stops at the balance and the CTA fits',page.locator('.avd-put__count').inner_text()=='30' and not page.locator('[data-draw="plus"]').is_enabled() and page.locator('.avd-cta').evaluate('e=>e.scrollWidth<=e.clientWidth'))
    js('for(let i=0;i<27;i++)document.querySelector("[data-draw=minus]").click()')
    before=js('AV.S.tickets');prize=page.locator('.avd-prize.is-selected').get_attribute('data-prize')
    prize_id=js(f'AV.D.DRAW.prizes[{prize}].id');previous=js(f'AV.S.draw[{prize_id!r}]||0')
    grid=page.locator('.avd-prizes').element_handle()
    page.locator('[data-draw="put"]').click()
    js("AV_GAME.click({dataset:{draw:'put'}},AV.gameCtx())")
    page.wait_for_function('document.querySelector("[data-draw=put]")&&!document.querySelector("[data-draw=put]").disabled')
    check('ticket transfer preserves the same choice grid and selection',grid.evaluate('e=>e.isConnected') and page.locator('.avd-prize.is-selected').get_attribute('data-prize')==prize)
    check('raffle transfers tickets once to the selected prize',js('AV.S.tickets')==before-3 and js(f'AV.S.draw[{prize_id!r}]')==previous+3 and js('AV.S.events.filter(e=>e.name==="raffle_tickets").length')==1)
    page.goto(base+'?state=draw-none')
    page.locator('[data-draw="earn"]').click();page.wait_for_selector('#game .nw-wheel')
    check('no-ticket raffle returns to the wheel',js('AV.current()')=='game')
    page.goto(base+'?state=stat%3A01.01')
    page.wait_for_function('document.querySelector(".avc-cookie__whole").complete')
    check('wrapped cookie asset loads',page.locator('.avc-cookie__whole').get_attribute('src')=='renders/fortune-cookie-cyan.webp' and page.locator('.avc-cookie__whole').evaluate('e=>e.naturalWidth>0'))
    page.locator('#stat-share').click();page.wait_for_selector('.avc.is-cracked')
    check('cookie reveals fortune and share action',page.locator('.avc-paper').is_visible() and 'ПОДЕЛИТЬСЯ' in page.locator('#stat-share').inner_text())
    check('cracked state uses matching fractured halves',all('fortune-cookie-broken.webp' in s for s in page.locator('.avc-cookie__half').evaluate_all('els=>els.map(e=>e.src)')))
    for w,h in [(375,667),(390,844),(430,932)]:
        page.set_viewport_size({'width':w,'height':h})
        for state in ['home','task-help','task-help:share','wheel','wheel-poor','wheel-empty','draw','draw-none','garland-decoration','stat:01.01','cracked:01.01']:
            js(f'AV.showState({state!r})');page.wait_for_timeout(150)
            if state=='home':
                page.evaluate('document.fonts.ready')
                check(f'entry labels are fully visible at {w}',page.locator('.av-entry__title').evaluate_all('els=>els.every(e=>{const range=document.createRange();range.selectNodeContents(e);const r=range.getBoundingClientRect(),b=e.closest("button").getBoundingClientRect();return r.left>=b.left+4&&r.right<=b.right-4&&r.bottom<=b.bottom-4;})'))
            if state.startswith('draw'):
                check(f'raffle cards and CTA fit {w}x{h}',page.locator('.avd-prize__title').evaluate_all('els=>els.every(e=>e.scrollWidth<=e.clientWidth+1&&e.scrollHeight<=e.clientHeight+1)') and page.locator('.avd-cta').evaluate('e=>{const r=e.getBoundingClientRect();return r.bottom<=innerHeight&&r.left>=0&&r.right<=innerWidth;}'))
            if state.startswith('task-help'):
                page.locator('#task-help-action').click(trial=True)
