            check(f'{state} fits {w}x{h}',js('document.documentElement.scrollWidth<=innerWidth') and js("() => {const e=document.querySelector('#game>.nw');return AV.current()!=='game'||e.scrollHeight<=e.clientHeight+1;}"))
